/* login-art-data.js
   Gambar karakter halaman login (login-art.webp) yang ditanam sebagai data URI.
   Kenapa: WebGL tidak boleh memakai gambar lokal bila halaman dibuka langsung dari file (file://) —
   browser memblokirnya (CORS). Data URI selalu diizinkan, jadi halftone tampil di mana pun halaman dibuka
   (klik dua kali index.html, Live Server, GitHub Pages).
   File ini dihasilkan dari login-art.webp. Ganti karakter? Minta dibuatkan ulang, atau ubah gambar jadi base64
   lalu tempel setelah "data:image/webp;base64,". Kalau file ini tidak ada, app.js otomatis memakai login-art.webp
   (berfungsi bila situs dibuka lewat http/https). */
window.LOGIN_ART_DATA = "data:image/webp;base64,";
